-- =============================================================
-- IMPORTAÇÃO DOS ESTOQUES BM36 + WORLD CLASSIC
-- Fonte: planilhas de estoque físico de 12/08/2026
-- PostgreSQL / Railway
--
-- O script:
-- 1) adapta a tabela produtos para guardar os campos das planilhas;
-- 2) permite o mesmo "Código" em empresas/origens diferentes;
-- 3) importa/atualiza 6.755 produtos;
-- 4) registra o estoque físico como movimentação, preservando histórico;
-- 5) é seguro para reexecução: não duplica a movimentação desta importação.
-- =============================================================

BEGIN;

-- -------------------------------------------------------------
-- 1. Ajustes de estrutura
-- -------------------------------------------------------------

ALTER TABLE produtos
    ADD COLUMN IF NOT EXISTS origem VARCHAR(50),
    ADD COLUMN IF NOT EXISTS codigo_fabricante VARCHAR(120),
    ADD COLUMN IF NOT EXISTS tipo_planilha VARCHAR(20);

-- A planilha não possui preço de venda. Permitimos NULL para não inventar preço.
ALTER TABLE produtos
    ALTER COLUMN preco_venda DROP NOT NULL,
    ALTER COLUMN preco_venda DROP DEFAULT;

-- O código interno se repete entre BM36 e WORLD CLASSIC.
-- Portanto, a unicidade correta é (origem, codigo).
ALTER TABLE produtos
    DROP CONSTRAINT IF EXISTS produtos_codigo_key;

CREATE UNIQUE INDEX IF NOT EXISTS uq_produtos_origem_codigo
    ON produtos(origem, codigo);

-- Marca a importação de estoque para impedir duplicidade ao rodar o script de novo.
ALTER TABLE movimentacoes_estoque
    ADD COLUMN IF NOT EXISTS referencia_importacao VARCHAR(100);

CREATE UNIQUE INDEX IF NOT EXISTS uq_movimentacao_importacao
    ON movimentacoes_estoque(produto_id, referencia_importacao);

-- Usuário técnico, inativo, usado apenas para registrar a origem da importação.
INSERT INTO usuarios (
    nome,
    email,
    senha_hash,
    cargo,
    perfil,
    ativo
)
VALUES (
    'Importação de Planilhas',
    'importacao.planilhas@bm36.local',
    'CONTA_TECNICA_SEM_LOGIN',
    'Sistema',
    'FUNCIONARIO',
    FALSE
)
ON CONFLICT (email) DO NOTHING;

-- Remove somente os dois registros de teste criados durante a configuração.
DELETE FROM produtos
WHERE origem IS NULL
  AND codigo IN ('PROD001', 'PROD002');

-- -------------------------------------------------------------
-- 2. Produtos
-- Colunas importadas:
-- origem, código, descrição/nome, T, embalagem e código do fabricante.
-- categoria_id fica NULL porque as planilhas não possuem categoria.
-- preco_venda fica NULL porque as planilhas não possuem preço de venda.
-- -------------------------------------------------------------


INSERT INTO produtos (
    origem,
    codigo,
    nome,
    descricao,
    codigo_fabricante,
    tipo_planilha,
    quantidade_por_caixa,
    preco_venda,
    estoque_minimo,
    ativo
)
