),
usuario_importacao AS (
    SELECT id
    FROM usuarios
    WHERE email = 'importacao.planilhas@bm36.local'
    LIMIT 1
)
INSERT INTO movimentacoes_estoque (
    produto_id,
    usuario_id,
    tipo,
    quantidade,
    motivo,
    referencia_importacao
)
SELECT
    p.id,
    u.id,
    CASE
        WHEN e.estoque_fisico > 0 THEN 'ENTRADA'
        ELSE 'AJUSTE_NEGATIVO'
    END,
    ABS(e.estoque_fisico),
    'Importação do estoque físico em 12/08/2026 - ' || e.origem,
    e.referencia
FROM estoque_importado e
JOIN produtos p
  ON p.origem = e.origem
 AND p.codigo = e.codigo
CROSS JOIN usuario_importacao u
ON CONFLICT (produto_id, referencia_importacao) DO NOTHING;


