),
usuario_importacao AS (
    SELECT id
    FROM usuarios
    WHERE email = 'importacao.planilhas@bm36.local'
    LIMIT 1
)
INSERT INTO movimentacoes_estoque (
    produto_id,
    usuario_id,
    tipo,
    quantidade,
    motivo,
    referencia_importacao
)
SELECT
    p.id,
    u.id,
    CASE
        WHEN e.estoque_fisico > 0 THEN 'ENTRADA'
        ELSE 'AJUSTE_NEGATIVO'
    END,
    ABS(e.estoque_fisico),
    'Importação do estoque físico em 12/08/2026 - ' || e.origem,
    e.referencia
FROM estoque_importado e
JOIN produtos p
  ON p.origem = e.origem
 AND p.codigo = e.codigo
CROSS JOIN usuario_importacao u
ON CONFLICT (produto_id, referencia_importacao) DO NOTHING;


COMMIT;

-- -------------------------------------------------------------
-- 4. Conferências úteis após a importação
-- -------------------------------------------------------------

-- Quantidade de produtos por origem:
SELECT origem, COUNT(*) AS quantidade
FROM produtos
WHERE origem IN ('BM36', 'WORLD CLASSIC')
GROUP BY origem
ORDER BY origem;

-- Consulta com estoque atual:
SELECT
    p.origem,
    p.codigo,
    p.nome,
    p.codigo_fabricante,
    p.tipo_planilha,
    p.quantidade_por_caixa,
    p.preco_venda,
    COALESCE(
        SUM(
            CASE
                WHEN m.tipo IN ('ENTRADA', 'AJUSTE_POSITIVO') THEN m.quantidade
                WHEN m.tipo IN ('SAIDA', 'VENDA', 'AJUSTE_NEGATIVO') THEN -m.quantidade
                ELSE 0
            END
        ),
        0
    ) AS estoque_atual
FROM produtos p
LEFT JOIN movimentacoes_estoque m
       ON m.produto_id = p.id
WHERE p.origem IN ('BM36', 'WORLD CLASSIC')
GROUP BY
    p.id,
    p.origem,
    p.codigo,
    p.nome,
    p.codigo_fabricante,
    p.tipo_planilha,
    p.quantidade_por_caixa,
    p.preco_venda
ORDER BY p.origem, p.codigo;

